plurals.en.ui.guidesCount:
(n: number) => {
      const mod100 = n % 100;
      const word =
        n === 0
          ? 'دليل'
          : n === 1
            ? 'دليل'
            : n === 2
              ? 'دليلان'
              : mod100 >= 3 && mod100 <= 10
                ? 'دلة'
                : mod100 >= 11 && mod100 <= 99
                  ? 'دليل'
                  : 'دليل';
      return `${n} ${word}`;
    }

